"""Demo 1: E8 representation numbers as 240*sigma_3(n)."""
from typing import List

def divisors(n: int) -> List[int]:
    ds = []
    d = 1
    while d * d <= n:
        if n % d == 0:
            ds.append(d)
            if d != n // d:
                ds.append(n // d)
        d += 1
    return sorted(ds)

def sigma(k: int, n: int) -> int:
    return sum(d ** k for d in divisors(n))

def rE8(n: int) -> int:
    return 240 * sigma(3, n)

if __name__ == "__main__":
    print(f"{'n':>3} | {'sigma_3(n)':>12} | {'r_E8(n)':>14}")
    for n in range(1, 13):
        print(f"{n:>3} | {sigma(3, n):>12} | {rE8(n):>14}")
    assert rE8(1) == 240 and rE8(2) == 2160
    print("r_E8(1)=240 (the 240 roots); r_E8(2)=2160.  OK")

"""Demo 2: Hecke three-term recurrence and prime-power geometric form."""
from typing import List

def divisors(n: int) -> List[int]:
    ds = []
    d = 1
    while d * d <= n:
        if n % d == 0:
            ds.append(d)
            if d != n // d:
                ds.append(n // d)
        d += 1
    return sorted(ds)

def sigma3(n: int) -> int:
    return sum(d ** 3 for d in divisors(n))

def sigma3_closed(p: int, a: int) -> int:
    return (p ** (3 * (a + 1)) - 1) // (p ** 3 - 1)

if __name__ == "__main__":
    for p in (2, 3, 5, 7):
        for a in range(5):
            assert sigma3(p ** a) == sigma3_closed(p, a)
        for r in range(4):
            lhs = sigma3(p ** (r + 2)) + p ** 3 * sigma3(p ** r)
            rhs = sigma3(p) * sigma3(p ** (r + 1))
            assert lhs == rhs
        print(f"p={p}: geometric form and Hecke recurrence verified.  OK")

"""Demo 3: Global Hecke convolution identity and its diagonal."""
from math import gcd
from typing import List

def divisors(n: int) -> List[int]:
    ds = []
    d = 1
    while d * d <= n:
        if n % d == 0:
            ds.append(d)
            if d != n // d:
                ds.append(n // d)
        d += 1
    return sorted(ds)

def sigma3(n: int) -> int:
    return sum(d ** 3 for d in divisors(n))

def hecke_rhs(m: int, n: int) -> int:
    g = gcd(m, n)
    return sum(d ** 3 * sigma3((m * n) // (d * d)) for d in divisors(g))

if __name__ == "__main__":
    for m in range(1, 9):
        for n in range(1, 9):
            assert sigma3(m) * sigma3(n) == hecke_rhs(m, n)
    print("Global Hecke identity verified for 1<=m,n<=8.  OK")
    for n in range(1, 8):
        lhs = sigma3(n) ** 2
        rhs = sum(d ** 3 * sigma3((n * n) // (d * d)) for d in divisors(n))
        assert lhs == rhs
        print(f"diagonal n={n}: sigma_3(n)^2 = {lhs}")

"""Demo 4: Primality characterization sigma_3(n)=n^3+1 iff n prime, plus congruence."""
from typing import List

def divisors(n: int) -> List[int]:
    ds = []
    d = 1
    while d * d <= n:
        if n % d == 0:
            ds.append(d)
            if d != n // d:
                ds.append(n // d)
        d += 1
    return sorted(ds)

def sigma(k: int, n: int) -> int:
    return sum(d ** k for d in divisors(n))

def is_prime(n: int) -> bool:
    return n >= 2 and all(n % d for d in range(2, int(n ** 0.5) + 1))

if __name__ == "__main__":
    for n in range(2, 30):
        s3 = sigma(3, n)
        assert n ** 3 <= s3 and n ** 3 + 1 <= s3
        assert (s3 == n ** 3 + 1) == is_prime(n)
        assert (sigma(3, n) - sigma(1, n)) % 6 == 0
    print("Primality characterization and sigma_3 ≡ sigma_1 (mod 6) verified.  OK")

