function DIVISOR_POWER_SUM(k, n):
    require n >= 1
    total <- 0
    d <- 1
    while d*d <= n:
        if n mod d == 0:
            total <- total + d^k
            e <- n / d
            if e != d:
                total <- total + e^k
        d <- d + 1
    return total

