from typing import List

def divisor_power_sum(k: int, n: int) -> int:
    """Compute sigma_k(n) = sum_{d | n} d^k in O(sqrt(n)) via paired trial division."""
    if n < 1:
        raise ValueError("n >= 1 required")
    total = 0
    d = 1
    while d * d <= n:
        if n % d == 0:
            total += d ** k
            e = n // d
            if e != d:
                total += e ** k
        d += 1
    return total

