function HECKE_IDENTITY_HOLDS(m, n):
    g <- gcd(m, n)
    rhs <- 0
    for each d dividing g:
        rhs <- rhs + d^3 * sigma3((m*n) / (d*d))
    return sigma3(m) * sigma3(n) == rhs

