def hecke_identity_holds(m: int, n: int) -> bool:
    """Return True iff sigma_3(m) sigma_3(n) = sum_{d|gcd(m,n)} d^3 sigma_3(mn/d^2)."""
    g = gcd(m, n)
    rhs = sum(d ** 3 * sigma3((m * n) // (d * d)) for d in divisors(g))
    return sigma3(m) * sigma3(n) == rhs

