def e4_squared_holds(n: int) -> bool:
    """Check sigma_7(n) = sigma_3(n) + 120 * sum_{m=1}^{n-1} sigma_3(m) sigma_3(n-m).
    Equivalent to the coefficient identity E4^2 = E8 (dim M_8 = 1)."""
    conv = sum(sigma(3, m) * sigma(3, n - m) for m in range(1, n))
    return sigma(7, n) == sigma(3, n) + 120 * conv

