def is_prime_via_sigma3(n: int) -> bool:
    """Primality test using the E4 Fourier coefficients: for n >= 2,
    n is prime iff sigma_3(n) = n^3 + 1 (its minimum possible value)."""
    if n < 2:
        return False
    return sigma3(n) == n ** 3 + 1

